WITH exploded AS (SELECT id, host, log_ts, level, key, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, value), kept_keys AS (SELECT level, host FROM exploded EXCEPT ALL SELECT level, host FROM app_logs WHERE service = 'auth'), verified AS (SELECT s.* FROM exploded s INNER JOIN kept_keys k ON s.level = k.level AND s.host = k.host), filtered AS (SELECT *, TRIM(level) AS clean_level FROM verified WHERE log_ts >= TO_TIMESTAMP('2025-06-01 16:00:00')), valid AS (SELECT *, UPPER(level) AS level_upper, TRIM(level) AS clean_level_2 FROM filtered WHERE key IS NOT NULL AND log_ts >= TIMESTAMP '2025-06-01 13:00:00'), cleaned AS (SELECT id, host, log_ts, value, level_upper, clean_level_2, CASE WHEN key = 'version' THEN 1 ELSE 0 END AS is_version FROM valid WHERE key IS NOT NULL) SELECT host, COUNT(CASE WHEN host = 'h2' THEN 1 END) AS h2_count, COUNT_IF(host = 'h3') AS h3_events, ROUND(AVG(is_version), 2) AS avg_is_version, SUM(CASE WHEN host = 'h2' THEN is_version ELSE 0 END) AS h2_is_version, MIN(log_ts) AS first_seen, SIZE(COLLECT_SET(host)) AS num_hosts FROM cleaned GROUP BY 1 HAVING COUNT_IF(host = 'h3') > 1 ORDER BY h2_is_version NULLS FIRST
